  final deadline = SessionDeadline(clock: clock);
  final raw = envValue?.trim();
  if (raw != null && raw.isNotEmpty) {
    final epoch = int.tryParse(raw);
    if (epoch != null && epoch >= deadlineEpochMsFloor) {
      try {
        deadline.setEpochMs(epoch);
      } on FormatException {
