        // keyboard (a past deadline is the host's stale export, not a
        // typo to nag about).
      }
    }
  }
  final flag = flagSpec?.trim();
  if (flag != null && flag.isNotEmpty) {
    deadline.setFromSpec(flag);
  }
  return deadline;
}

