  /// Creates a ladder. [wrapUpSteerMs] defaults to T-3min, [finalAnswerMs]
  /// to T-30s.
  const DeadlineLadder({
    this.wrapUpSteerMs = 3 * 60 * 1000,
    this.finalAnswerMs = 30 * 1000,
